type Settings = {
    effortLevel?: "high" | "low" | "medium" | "xhigh";
    inputNeededNotifEnabled?: boolean;
    model?: string;
    permissions?: {
        [k: string]: unknown;
        allow?: string[] | undefined;
        deny?: string[] | undefined;
        ask?: string[] | undefined;
        defaultMode?: "acceptEdits" | "auto" | "bypassPermissions" | "default" | "dontAsk" | "plan" | undefined;
        disableBypassPermissionsMode?: "disable" | undefined;
        blockReadsOutsideWorkingDirectories?: boolean | undefined;
        additionalDirectories?: string[] | undefined;
    };
    teammateMode?: "auto" | "in-process" | "iterm2" | "tmux";
    theme?: string;
}

(property) permissions?: {
    [k: string]: unknown;
    allow?: string[] | undefined;
    deny?: string[] | undefined;
    ask?: string[] | undefined;
    defaultMode?: "acceptEdits" | "auto" | "bypassPermissions" | "default" | "dontAsk" | "plan" | undefined;
    disableBypassPermissionsMode?: "disable" | undefined;
    blockReadsOutsideWorkingDirectories?: boolean | undefined;
    additionalDirectories?: string[] | undefined;
} | undefined
